"""Unit tests for projects generated by the `snickerdoodle` template."""

from __future__ import annotations

import importlib.util
import pathlib
import py_compile
import shutil
import subprocess
import sys
import tomllib
from typing import TYPE_CHECKING, Any

import pytest
import yaml

if TYPE_CHECKING:
    import types

    from pytest_cookies.plugin import Cookies, Result

ROOT: pathlib.Path = pathlib.Path(__file__).parent.parent
CONTEXT: dict[str, Any] = {
    'project_name': 'Cookie Jar',
    'author_name': 'Test Author',
    'author_email': 'test@example.com',
    'github_user': 'WithPrecedent',
    'description': 'A test project.'}
OPTIONS: list[str] = [
    'github_actions',
    'pre_commit',
    'dependabot',
    'mkdocs',
    'mypy',
    'pypi',
    'code_coverage']


def bake(cookies: Cookies, **kwargs: Any) -> Result:
    """Bakes a project and checks that it was created.

    Args:
        cookies: the `pytest-cookies` fixture.
        kwargs: values that replace those in `CONTEXT`.

    Returns:
        The result of baking the project.

    """
    result = cookies.bake(extra_context = CONTEXT | kwargs)
    assert result.exception is None, result.exception
    assert result.exit_code == 0
    assert result.project_path is not None
    return result


def load_hook(name: str) -> types.ModuleType:
    """Imports an (unrendered) hook script as a module.

    Args:
        name: name of the hook file without its extension.

    Returns:
        The imported hook module.

    """
    path = ROOT / 'hooks' / f'{name}.py'
    spec = importlib.util.spec_from_file_location(name, path)
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


""" Default Project """

def test_default_project(cookies: Cookies) -> None:
    result = bake(cookies)
    path = result.project_path
    assert path.name == 'cookie_jar'
    assert (path / 'src' / 'cookie_jar' / '__init__.py').is_file()
    assert (path / 'tests' / 'test_main.py').is_file()
    for name in [
            '.editorconfig',
            '.github/dependabot.yml',
            '.github/workflows/ci.yml',
            '.github/workflows/publish.yml',
            '.github/workflows/validate_codecov.yml',
            '.pre-commit-config.yaml',
            'codecov.yml',
            'docs',
            'mkdocs.yml']:
        assert (path / name).exists(), name

def test_no_unrendered_templates(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    for file in path.rglob('*'):
        if file.is_file() and file.suffix not in ('.png', '.ico'):
            text = file.read_text(encoding = 'utf-8')
            assert 'cookiecutter.' not in text, file
            assert '{%' not in text, file

def test_names(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    pyproject = tomllib.loads((path / 'pyproject.toml').read_text())
    assert pyproject['project']['name'] == 'cookie-jar'
    assert pyproject['tool']['hatch']['build']['targets']['wheel'][
        'packages'] == ['src/cookie_jar']
    readme = (path / 'README.md').read_text(encoding = 'utf-8')
    assert 'pip install cookie-jar' in readme
    mkdocs = (path / 'mkdocs.yml').read_text(encoding = 'utf-8')
    assert 'https://pypi.org/project/cookie-jar/' in mkdocs

def test_readme_license_link(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    readme = (path / 'README.md').read_text(encoding = 'utf-8')
    assert '/blob/main/LICENSE' in readme

def test_python_files_compile(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    for file in path.rglob('*.py'):
        py_compile.compile(str(file), doraise = True)

def test_package_imports(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    process = subprocess.run(  # noqa: S603
        [sys.executable, '-c', 'import cookie_jar; print(cookie_jar.__version__)'],
        cwd = path / 'src',
        capture_output = True,
        text = True,
        check = False)
    assert process.returncode == 0, process.stderr
    assert process.stdout.strip() == '0.0.1'

def test_generated_tests_pass(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    process = subprocess.run(  # noqa: S603
        [sys.executable, '-m', 'pytest', '-p', 'no:cacheprovider', '-q'],
        cwd = path,
        capture_output = True,
        text = True,
        check = False)
    assert process.returncode == 0, process.stdout + process.stderr

@pytest.mark.skipif(shutil.which('ruff') is None, reason = 'ruff not found')
def test_ruff_passes(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    process = subprocess.run(  # noqa: S603
        ['ruff', 'check', '--no-fix', '.'],  # noqa: S607
        cwd = path,
        capture_output = True,
        text = True,
        check = False)
    assert process.returncode == 0, process.stdout

""" Configuration Files """

@pytest.mark.parametrize('enabled', [True, False])
def test_configuration_files_parse(cookies: Cookies, enabled: bool) -> None:
    options = dict.fromkeys(OPTIONS, enabled) | {'github_actions': True}
    path = bake(cookies, **options).project_path
    tomllib.loads((path / 'pyproject.toml').read_text())
    for file in path.rglob('*.yml'):
        if file.name != 'mkdocs.yml':
            yaml.safe_load(file.read_text(encoding = 'utf-8'))
    for file in path.rglob('*.yaml'):
        yaml.safe_load(file.read_text(encoding = 'utf-8'))

def test_ci_workflow_jobs(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    ci = yaml.safe_load((path / '.github/workflows/ci.yml').read_text())
    assert set(ci['jobs']) == {
        'build_and_test',
        'lint_and_format',
        'document_and_deploy',
        'create_github_release'}
    steps = [step['name'] for step in ci['jobs']['lint_and_format']['steps']]
    assert 'run mypy' in steps
    steps = [step['name'] for step in ci['jobs']['build_and_test']['steps']]
    assert 'run pre-commit' in steps

def test_ci_workflow_without_options(cookies: Cookies) -> None:
    path = bake(
        cookies,
        mkdocs = False,
        mypy = False,
        pre_commit = False).project_path
    ci = yaml.safe_load((path / '.github/workflows/ci.yml').read_text())
    assert 'document_and_deploy' not in ci['jobs']
    steps = [step['name'] for step in ci['jobs']['lint_and_format']['steps']]
    assert 'run mypy' not in steps
    steps = [step['name'] for step in ci['jobs']['build_and_test']['steps']]
    assert 'run pre-commit' not in steps

def test_pre_commit_does_not_format(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    config = yaml.safe_load((path / '.pre-commit-config.yaml').read_text())
    hooks = [hook['id'] for repo in config['repos'] for hook in repo['hooks']]
    assert 'ruff' in hooks
    assert 'ruff-format' not in hooks

""" Whitespace """

@pytest.mark.parametrize('enabled', [True, False])
def test_files_end_with_newline(cookies: Cookies, enabled: bool) -> None:
    options = dict.fromkeys(OPTIONS, enabled) | {'github_actions': True}
    path = bake(cookies, **options).project_path
    for file in path.rglob('*'):
        if file.is_file() and file.suffix not in ('.png', '.ico'):
            text = file.read_text(encoding = 'utf-8')
            if text:
                assert text.endswith('\n'), file
                assert not text.endswith('\n\n'), file

@pytest.mark.parametrize('enabled', [True, False])
def test_no_trailing_whitespace(cookies: Cookies, enabled: bool) -> None:
    options = dict.fromkeys(OPTIONS, enabled) | {'github_actions': True}
    path = bake(cookies, **options).project_path
    for file in path.rglob('*'):
        if file.is_file() and file.suffix not in ('.png', '.ico'):
            text = file.read_text(encoding = 'utf-8')
            for number, line in enumerate(text.splitlines(), start = 1):
                assert line == line.rstrip(), f'{file}:{number}'

""" Optional Features """

@pytest.mark.parametrize(('option', 'paths'), [
    ('github_actions', ['.github/workflows']),
    ('pre_commit', ['.pre-commit-config.yaml']),
    ('dependabot', ['.github/dependabot.yml']),
    ('mkdocs', ['docs', 'mkdocs.yml']),
    ('pypi', ['.github/workflows/publish.yml']),
    ('code_coverage', [
        'codecov.yml',
        '.github/workflows/validate_codecov.yml'])])
def test_option_removes_paths(
        cookies: Cookies,
        option: str,
        paths: list[str]) -> None:
    path = bake(cookies, **{option: False}).project_path
    for name in paths:
        assert not (path / name).exists(), name

@pytest.mark.parametrize('value', ['y', 'Y', 'true', 'True', True])
def test_truthy_values(cookies: Cookies, value: str | bool) -> None:
    path = bake(cookies, mkdocs = value).project_path
    assert (path / 'mkdocs.yml').exists()

@pytest.mark.parametrize('value', ['n', 'N', 'false', 'False', False])
def test_falsy_values(cookies: Cookies, value: str | bool) -> None:
    path = bake(cookies, mkdocs = value).project_path
    assert not (path / 'mkdocs.yml').exists()

def test_mypy_option(cookies: Cookies) -> None:
    path = bake(cookies, mypy = True).project_path
    pyproject = tomllib.loads((path / 'pyproject.toml').read_text())
    assert 'mypy' in pyproject['tool']
    assert 'mypy' in pyproject['dependency-groups']['dev']
    path = bake(cookies, mypy = False).project_path
    pyproject = tomllib.loads((path / 'pyproject.toml').read_text())
    assert 'mypy' not in pyproject['tool']
    assert 'mypy' not in pyproject['dependency-groups']['dev']

def test_code_coverage_option(cookies: Cookies) -> None:
    path = bake(cookies, code_coverage = True).project_path
    pyproject = tomllib.loads((path / 'pyproject.toml').read_text())
    assert pyproject['tool']['coverage']['run']['source'] == [
        'cookie_jar',
        'tests']
    path = bake(cookies, code_coverage = False).project_path
    pyproject = tomllib.loads((path / 'pyproject.toml').read_text())
    assert 'coverage' not in pyproject['tool']

def test_code_coverage_uploads_to_codecov(cookies: Cookies) -> None:
    path = bake(cookies, code_coverage = True).project_path
    ci = yaml.safe_load((path / '.github/workflows/ci.yml').read_text())
    assert ci['permissions']['id-token'] == 'write'
    steps = {
        step['name']: step for step in ci['jobs']['build_and_test']['steps']}
    assert '--cov-report=xml' in steps['run tests']['run']
    upload = steps['upload coverage to codecov']
    assert upload['uses'].startswith('codecov/codecov-action@')
    assert upload['with'] == {'files': 'coverage.xml', 'use_oidc': True}
    readme = (path / 'README.md').read_text(encoding = 'utf-8')
    assert 'https://app.codecov.io/gh/WithPrecedent/cookie_jar' in readme
    path = bake(cookies, code_coverage = False).project_path
    ci = yaml.safe_load((path / '.github/workflows/ci.yml').read_text())
    assert 'id-token' not in ci['permissions']
    steps = {
        step['name']: step for step in ci['jobs']['build_and_test']['steps']}
    assert '--cov' not in steps['run tests']['run']
    assert 'upload coverage to codecov' not in steps
    readme = (path / 'README.md').read_text(encoding = 'utf-8')
    assert 'codecov' not in readme

def test_dependabot_updates_uv(cookies: Cookies) -> None:
    path = bake(cookies).project_path
    config = yaml.safe_load((path / '.github/dependabot.yml').read_text())
    ecosystems = {
        update['package-ecosystem']: update['directory']
        for update in config['updates']}
    assert ecosystems == {'uv': '/', 'github-actions': '/'}

@pytest.mark.parametrize(('license_name', 'text'), [
    ('MIT License', 'MIT License'),
    ('BSD License', 'BSD License'),
    ('ISC License', 'ISC License'),
    ('Apache Software License 2.0', 'Apache License'),
    ('GNU General Public License v3', 'GNU GENERAL PUBLIC LICENSE')])
def test_licenses(cookies: Cookies, license_name: str, text: str) -> None:
    path = bake(cookies, license = license_name).project_path
    license_text = (path / 'LICENSE').read_text(encoding = 'utf-8')
    assert text in license_text
    assert not license_text[0].isspace()
    assert license_text.endswith('\n')
    assert not license_text.endswith('\n\n')
    assert 'Test Author' in license_text

def test_other_license(cookies: Cookies) -> None:
    path = bake(cookies, license = 'Other').project_path
    assert (path / 'LICENSE').read_text(encoding = 'utf-8') == ''

@pytest.mark.parametrize('style', [
    'for-the-badge',
    'flat',
    'flat-square',
    'plastic',
    'social'])
def test_badge_styles(cookies: Cookies, style: str) -> None:
    path = bake(cookies, badge_style = style).project_path
    readme = (path / 'README.md').read_text(encoding = 'utf-8')
