""" Name Validation """

@pytest.mark.parametrize(('project_name', 'package', 'repo'), [
    ('cookie', 'cookie', 'cookie'),
    ('Cookie Jar', 'cookie-jar', 'cookie_jar'),
    ('cookie-jar', 'cookie-jar', 'cookie_jar'),
    ('cookie_jar', 'cookie-jar', 'cookie_jar'),
    ('Cookie2', 'cookie2', 'cookie2')])
def test_valid_names(
        cookies: Cookies,
        project_name: str,
        package: str,
        repo: str) -> None:
    path = bake(cookies, project_name = project_name).project_path
    assert path.name == repo
    assert (path / 'src' / repo).is_dir()
    pyproject = tomllib.loads((path / 'pyproject.toml').read_text())
    assert pyproject['project']['name'] == package

@pytest.mark.parametrize('project_name', [
    '',
    ' cookie',
    '-cookie',
    '_cookie',
    'cookie-',
    'cookie!',
    '2cookie',
    'class'])
def test_invalid_project_names(cookies: Cookies, project_name: str) -> None:
    result = cookies.bake(
        extra_context = CONTEXT | {'project_name': project_name})
    assert result.exit_code != 0
    assert result.project_path is None

def test_invalid_github_user(cookies: Cookies) -> None:
    result = cookies.bake(extra_context = CONTEXT | {'github_user': ''})
    assert result.exit_code != 0

""" Hooks """

def test_post_gen_cleans_up_before_commit(
        monkeypatch: pytest.MonkeyPatch) -> None:
    hook = load_hook('post_gen_project')
    calls: list[str] = []
    monkeypatch.setattr(
        hook,
        '_TRUES',
        (*hook._TRUES, '{{ cookiecutter.commit_to_github }}'))
    monkeypatch.setattr(hook, 'cleanup_files', lambda: calls.append('clean'))
    monkeypatch.setattr(
        hook,
        'commit_to_git',
        lambda **_: calls.append('commit'))
    hook.main()
    assert calls == ['clean', 'commit']

def test_delete_path(tmp_path: pathlib.Path) -> None:
    hook = load_hook('post_gen_project')
    folder = tmp_path / 'folder'
    folder.mkdir()
    (folder / 'file.txt').write_text('text')
    file = tmp_path / 'file.txt'
    file.write_text('text')
    hook.delete_path(folder)
    hook.delete_path(str(file))
    hook.delete_path(tmp_path / 'missing.txt')
    assert not folder.exists()
    assert not file.exists()

@pytest.mark.parametrize(('text', 'valid'), [
    ('https://github.com/WithPrecedent/cookie_jar', True),
    ('https://github.com/With-Precedent/cookie_jar/', True),
    ('https://github.com//cookie_jar', False),
    ('https://github.com/With--Precedent/cookie_jar', False),
    ('https://gitlab.com/WithPrecedent/cookie_jar', False)])
def test_repo_url_validation(text: str, valid: bool) -> None:
    hook = load_hook('pre_gen_project')
    if valid:
        hook.validate_text(text, hook.VALID_REPO_URL, 'url')
    else:
        with pytest.raises(ValueError, match = 'not a valid url'):
            hook.validate_text(text, hook.VALID_REPO_URL, 'url')


if __name__ == '__main__':
    pytest.main([__file__])
